void* nrf52::dispatch() {
  if( ac_pc >= dec_cache_size){
    cerr << "ArchC: Address out of bounds (pc=0x" << hex << ac_pc << ")." << endl;
    stop();
    longjmp(ac_env, AC_ACTION_STOP);
  }
  ac_instr_counter++;
  unsigned ins_id;
  instr_dec = (DEC_CACHE + (ac_pc));
  if ( !instr_dec->valid ){
    unsigned* ins_cache;
    decode_pc = ac_pc;
    quant = 0;
    ins_cache = (ISA.decoder)->Decode(reinterpret_cast<unsigned char*>(buffer), quant);
    instr_dec->valid = true;
    instr_dec->id = ins_cache ? ins_cache[IDENT]: 0;
    instr_dec->end_rot = IntRoutine[instr_dec->id];
    switch (ISA.instr_format_table[instr_dec->id]) {
      case 1:
        instr_dec->F_Type_Imm8.op = ins_cache[1];
        instr_dec->F_Type_Imm8.subop1 = ins_cache[2];
        instr_dec->F_Type_Imm8.rd1 = ins_cache[3];
        instr_dec->F_Type_Imm8.imm1 = ins_cache[4];
      break;
      case 2:
        instr_dec->F_Type_Alu3.op = ins_cache[1];
        instr_dec->F_Type_Alu3.subop2 = ins_cache[5];
        instr_dec->F_Type_Alu3.rm2 = ins_cache[6];
        instr_dec->F_Type_Alu3.rn2 = ins_cache[7];
        instr_dec->F_Type_Alu3.rd2 = ins_cache[8];
      break;
      case 3:
        instr_dec->F_Type_Alu2.op = ins_cache[1];
        instr_dec->F_Type_Alu2.subop3 = ins_cache[9];
        instr_dec->F_Type_Alu2.rm3 = ins_cache[7];
        instr_dec->F_Type_Alu2.rdn3 = ins_cache[8];
      break;
      case 4:
        instr_dec->F_Type_Mem.op = ins_cache[1];
        instr_dec->F_Type_Mem.subop4 = ins_cache[2];
        instr_dec->F_Type_Mem.imm4 = ins_cache[10];
        instr_dec->F_Type_Mem.rn4 = ins_cache[7];
        instr_dec->F_Type_Mem.rt4 = ins_cache[8];
      break;
      case 5:
        instr_dec->F_Type_BCond.op = ins_cache[1];
        instr_dec->F_Type_BCond.cond5 = ins_cache[11];
        instr_dec->F_Type_BCond.bdisp5 = ins_cache[12];
      break;
      case 6:
        instr_dec->F_Type_BUnc.op = ins_cache[13];
        instr_dec->F_Type_BUnc.bdisp6 = ins_cache[14];
      break;
      case 7:
        instr_dec->F_Type_Special.op = ins_cache[1];
        instr_dec->F_Type_Special.subop7 = ins_cache[11];
        instr_dec->F_Type_Special.imm7 = ins_cache[4];
      break;
      default:
        cerr << "ArchC Error: Unidentified instruction. " << endl;
        cerr << "PC = " << hex << ac_pc << dec << endl;
        stop();
        longjmp(ac_env, AC_ACTION_STOP);
    }
  }
  ins_id = instr_dec->id;

  return instr_dec->end_rot;
}

